    /* ============================ BLOQUES ============================ */
    '@lg': { title: 'Logic, proof and problem solving', desc: 'The real foundation is not numbers: it is what it means for something to be true, how that is checked, and what to do when a problem looks like nothing you have seen.' },
    '@ar': { title: 'Arithmetic and foundations', desc: 'The floor everything else stands on: counting, operating, and understanding what a number is.' },
