    '@tr': { title: 'Trigonometry', desc: 'The machine that turns angles into lengths. It was born measuring stars.' },
    '@fn': { title: 'Functions and analysis', desc: 'The study of change. From the graph to the limit, from the limit to the derivative and the integral: the heart of the final exam.' },
